mapper.sql:
run_id = #{runId}
AND plan_generation = #{planGeneration}
AND node_id = #{nodeId}
AND node_attempt = #{nodeAttempt}
AND segment_sequence = #{segmentSequence}

mapper.select:
SELECT DISTINCT ON (node_id) 
FROM alphafrog_agent_run_work_item
WHERE run_id = #{runId}
  AND plan_generation = #{planGeneration}
ORDER BY node_id, node_attempt DESC, segment_sequence DESC, id DESC

SELECT 
FROM alphafrog_agent_run_work_item
WHERE scheduler_version = #{schedulerVersion}
  AND state NOT IN ()
ORDER BY id
LIMIT #{limit}

SELECT COALESCE(MAX(plan_generation), -1)
FROM alphafrog_agent_run_work_item
WHERE run_id = #{runId}

UPDATE alphafrog_agent_run_work_item SET
    state = 'CLAIMED',
    claim_epoch = claim_epoch + 1,
    claimed_by = #{claimedBy},
    lease_expires_at = #{leaseExpiresAt},
    dispatch_defer_reason = NULL,
    updated_at = CURRENT_TIMESTAMP
WHERE 
  AND scheduler_version = #{schedulerVersion}
  AND state IN ('RUNNABLE', 'RESUMABLE')
  AND next_visible_at <= CURRENT_TIMESTAMP
  AND context_version = #{contextVersion}
  AND run_control_version = #{runControlVersion}
  AND EXISTS (
      SELECT 1
      FROM alphafrog_agent_run owner_run
      WHERE owner_run.id = #{runId}
        AND owner_run.plan_generation = #{planGeneration}
        AND owner_run.run_control_version = #{runControlVersion}
        AND owner_run.status IN ('RECEIVED', 'EXECUTING')
  )
RETURNING claim_epoch

mapper.update:
UPDATE alphafrog_agent_run_work_item SET
    state = 'RESULT_COMMITTED',
    payload_json = payload_json || COALESCE(CAST(#{payloadPatchJson} AS jsonb), '{}'::jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE 
  AND state = 'EXECUTING'
  AND context_version = #{contextVersion}
  AND run_control_version = #{runControlVersion}
  AND claim_epoch = #{claimEpoch}
  AND EXISTS (
      SELECT 1
      FROM alphafrog_agent_run owner_run
      WHERE owner_run.id = #{runId}
        AND owner_run.plan_generation = #{planGeneration}
        AND owner_run.run_control_version = #{runControlVersion}
        AND owner_run.status = 'EXECUTING'
  )

UPDATE alphafrog_agent_run_work_item wi SET
    state = 'WAITING',
    claimed_by = NULL,
    lease_expires_at = NULL,
    payload_json = wi.payload_json || jsonb_build_object(
        'toolJobWait', jsonb_build_object(
            'operationId', #{operationId}::text,
            'toolCallId', #{toolCallId}::text,
            'attempt', #{attempt}::int)),
    updated_at = CURRENT_TIMESTAMP
WHERE 
  AND wi.state = 'EXECUTING'
  AND wi.context_version = #{contextVersion}
  AND wi.run_control_version = #{runControlVersion}
  AND wi.claim_epoch = #{claimEpoch}
  AND wi.claimed_by = #{claimedBy}
  AND EXISTS (
      SELECT 1
      FROM alphafrog_agent_run owner_run
      WHERE owner_run.id = #{runId}
        AND owner_run.status = 'WAITING_TOOL_JOB'
        AND owner_run.plan_generation = #{planGeneration}
        AND owner_run.run_control_version = #{runControlVersion}
        AND owner_run.tool_job_anchor_json #>> '{operationId}' = #{operationId}
        AND owner_run.tool_job_anchor_json #>> '{toolCallId}' = #{toolCallId}
        AND owner_run.tool_job_anchor_json #>> '{attempt}' = #{attempt}::text
        AND owner_run.tool_job_anchor_json #>> '{workItemPlanGeneration}' = #{planGeneration}::text
        AND owner_run.tool_job_anchor_json #>> '{workItemNodeId}' = #{nodeId}
        AND owner_run.tool_job_anchor_json #>> '{workItemNodeAttempt}' = #{nodeAttempt}::text
        AND owner_run.tool_job_anchor_json #>> '{workItemSegmentSequence}' = #{segmentSequence}::text
        AND owner_run.tool_job_anchor_json #>> '{workItemContextVersion}' = #{contextVersion}::text
        AND owner_run.tool_job_anchor_json #>> '{workItemRunControlVersion}' = #{runControlVersion}::text
        AND owner_run.tool_job_anchor_json #>> '{workItemClaimEpoch}' = #{claimEpoch}::text)

WITH run_locked AS (
    SELECT owner_run.id
    FROM alphafrog_agent_run owner_run
    WHERE owner_run.id = #{runId}
      AND owner_run.status = 'WAITING_TOOL_JOB'
      AND owner_run.plan_generation = #{planGeneration}
      AND owner_run.run_control_version = #{runControlVersion}
      AND owner_run.tool_job_anchor_json #>> '{operationId}' = #{operationId}
      AND owner_run.tool_job_anchor_json #>> '{workItemPlanGeneration}' = #{planGeneration}::text
      AND owner_run.tool_job_anchor_json #>> '{workItemNodeId}' = #{nodeId}
      AND owner_run.tool_job_anchor_json #>> '{workItemNodeAttempt}' = #{nodeAttempt}::text
      AND owner_run.tool_job_anchor_json #>> '{workItemSegmentSequence}' = #{segmentSequence}::text
      AND owner_run.tool_job_anchor_json #>> '{workItemContextVersion}' = #{contextVersion}::text
      AND owner_run.tool_job_anchor_json #>> '{workItemRunControlVersion}' = #{runControlVersion}::text
      AND owner_run.tool_job_anchor_json #>> '{workItemClaimEpoch}' = #{claimEpoch}::text
    FOR UPDATE
), item_locked AS (
    SELECT wi.id
    FROM alphafrog_agent_run_work_item wi
    WHERE 
      AND wi.state IN ('WAITING', 'EXECUTING')
      AND wi.context_version = #{contextVersion}
      AND wi.run_control_version = #{runControlVersion}
      AND wi.claim_epoch = #{claimEpoch}
      AND EXISTS (SELECT 1 FROM run_locked)
    FOR UPDATE
), run_advanced AS (
    UPDATE alphafrog_agent_run owner_run SET
        status = 'EXECUTING',
        tool_job_anchor_json = CAST(#{anchorJson} AS jsonb),
        updated_at = CURRENT_TIMESTAMP
    WHERE owner_run.id = #{runId}
      AND owner_run.status = 'WAITING_TOOL_JOB'
      AND owner_run.plan_generation = #{planGeneration}
      AND owner_run.run_control_version = #{runControlVersion}
      AND owner_run.tool_job_anchor_json #>> '{operationId}' = #{operationId}
      AND owner_run.tool_job_anchor_json #>> '{workItemPlanGeneration}' = #{planGeneration}::text
      AND owner_run.tool_job_anchor_json #>> '{workItemNodeId}' = #{nodeId}
      AND owner_run.tool_job_anchor_json #>> '{workItemNodeAttempt}' = #{nodeAttempt}::text
      AND owner_run.tool_job_anchor_json #>> '{workItemSegmentSequence}' = #{segmentSequence}::text
      AND owner_run.tool_job_anchor_json #>> '{workItemContextVersion}' = #{contextVersion}::text
      AND owner_run.tool_job_anchor_json #>> '{workItemRunControlVersion}' = #{runControlVersion}::text
      AND owner_run.tool_job_anchor_json #>> '{workItemClaimEpoch}' = #{claimEpoch}::text
      AND EXISTS (SELECT 1 FROM item_locked)
    RETURNING owner_run.id
)
UPDATE alphafrog_agent_run_work_item wi SET
    state = 'RESUMABLE',
    claimed_by = NULL,
    lease_expires_at = NULL,
    next_visible_at = CURRENT_TIMESTAMP,
    payload_json = wi.payload_json || jsonb_build_object(
        'toolJobResume', CAST(#{resumePayloadJson} AS jsonb)),
    updated_at = CURRENT_TIMESTAMP
WHERE 
  AND wi.state IN ('WAITING', 'EXECUTING')
  AND wi.context_version = #{contextVersion}
  AND wi.run_control_version = #{runControlVersion}
  AND wi.claim_epoch = #{claimEpoch}
  AND EXISTS (SELECT 1 FROM run_advanced)

WITH run_locked AS (
    SELECT owner_run.id
    FROM alphafrog_agent_run owner_run
    WHERE owner_run.id = #{runId}
      AND owner_run.status = 'EXECUTING'
      AND owner_run.plan_generation = #{planGeneration}
      AND owner_run.run_control_version = #{runControlVersion}
      AND owner_run.tool_job_anchor_json #>> '{operationId}' = #{operationId}
      AND owner_run.tool_job_anchor_json #>> '{resumeState}' = 'DUAL_POOL_READY'
      AND (owner_run.tool_job_anchor_json #>> '{workItemClaimEpoch}')::int < #{claimEpoch}
    FOR UPDATE
), item_committed AS (
    UPDATE alphafrog_agent_run_work_item wi SET
        state = 'RESULT_COMMITTED',
        payload_json = wi.payload_json
            || COALESCE(CAST(#{payloadPatchJson} AS jsonb), '{}'::jsonb)
            || jsonb_build_object('toolJobConsumed', true),
        updated_at = CURRENT_TIMESTAMP
    WHERE 
      AND wi.state = 'EXECUTING'
      AND wi.context_version = #{contextVersion}
      AND wi.run_control_version = #{runControlVersion}
      AND wi.claim_epoch = #{claimEpoch}
      AND EXISTS (SELECT 1 FROM run_locked)
    RETURNING wi.run_id
)
UPDATE alphafrog_agent_run owner_run SET
    tool_job_anchor_json = '{}'::jsonb,
    updated_at = CURRENT_TIMESTAMP
WHERE owner_run.id = #{runId}
  AND owner_run.tool_job_anchor_json #>> '{operationId}' = #{operationId}
  AND owner_run.tool_job_anchor_json #>> '{resumeState}' = 'DUAL_POOL_READY'
  AND EXISTS (SELECT 1 FROM item_committed)

UPDATE alphafrog_agent_run_work_item wi SET
    state = 'RESUMABLE',
    claimed_by = NULL,
    lease_expires_at = NULL,
    next_visible_at = CURRENT_TIMESTAMP,
    updated_at = CURRENT_TIMESTAMP
WHERE 
  AND wi.state IN ('CLAIMED', 'EXECUTING')
  AND wi.context_version = #{contextVersion}
  AND wi.run_control_version = #{runControlVersion}
  AND wi.claim_epoch = #{claimEpoch}
  AND EXISTS (
      SELECT 1
      FROM alphafrog_agent_run owner_run
      WHERE owner_run.id = #{runId}
        AND owner_run.status = 'EXECUTING'
        AND owner_run.plan_generation = #{planGeneration}
        AND owner_run.run_control_version = #{runControlVersion}
        AND owner_run.tool_job_anchor_json #>> '{operationId}' = #{operationId}
        AND owner_run.tool_job_anchor_json #>> '{resumeState}' = 'DUAL_POOL_READY'
        AND (owner_run.tool_job_anchor_json #>> '{workItemClaimEpoch}')::int < #{claimEpoch})
